// Text that contains a number.
const patterns = [
  [/^(\d+) images?$/, count => `${count} foto`],
  [/^(\d+) projects? shown\.$/, count => `${count} projekte të shfaqura.`],
];

// The same patterns read back, for text a script set while Albanian was shown.
const reversePatterns = [
  [/^(\d+) foto$/, count => `${count} ${count === "1" ? "image" : "images"}`],
  [/^(\d+) projekte të shfaqura\.$/, count => `${count} projects shown.`],
];

const supported = ["en", "sq"];
let language = "en";

export function currentLanguage() { return language; }

/** Translate one English string into the current language. */
export function t(text) {
  if (language === "en") return text;
  if (Object.prototype.hasOwnProperty.call(sq, text)) return sq[text];
  for (const [pattern, format] of patterns) {
    const match = text.match(pattern);
    if (match) return format(...match.slice(1));
  }
  return text;
}

export function hasTranslation(text) {
  return Object.prototype.hasOwnProperty.call(sq, text) || patterns.some(([pattern]) => pattern.test(text));
}

// English originals of every node and attribute we have changed.
const textOriginals = new WeakMap();
const attributeOriginals = new WeakMap();
const translatedAttributes = ["alt", "aria-label"];

const reverse = new Map(Object.entries(sq).map(([english, albanian]) => [albanian, english]));

function englishOf(store, node, current, key = "") {
  const saved = store.get(node)?.[key];
  if (saved && saved.shown === current) return saved.english;
  // A script replaced the text since the last switch, possibly already translated.
  const trimmed = current.trim();
  if (reverse.has(trimmed)) return current.replace(trimmed, reverse.get(trimmed));
  for (const [pattern, format] of reversePatterns) {
    const match = trimmed.match(pattern);
    if (match) return current.replace(trimmed, format(...match.slice(1)));
  }
  return current;
}

function remember(store, node, key, english, shown) {
  const record = store.get(node) || {};
  record[key] = { english, shown };
  store.set(node, record);
}

function translateTree(root) {
  const skip = node => node.parentElement?.closest('[translate="no"], [data-i18n-html], script, style');
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    if (skip(node) || !/\p{L}/u.test(node.nodeValue)) continue;
    const english = englishOf(textOriginals, node, node.nodeValue);
    const [, before, core, after] = english.match(/^(\s*)([\s\S]*?)(\s*)$/);
    const shown = before + t(core.replace(/\s+/g, " ")) + after;
    remember(textOriginals, node, "", english, shown);
    if (node.nodeValue !== shown) node.nodeValue = shown;
  }
  for (const element of root.querySelectorAll(translatedAttributes.map(name => `[${name}]`).join(","))) {
    if (element.closest('[translate="no"]')) continue;
    for (const name of translatedAttributes) {
      if (!element.hasAttribute(name)) continue;
      const english = englishOf(attributeOriginals, element, element.getAttribute(name), name);
      const shown = t(english);
      remember(attributeOriginals, element, name, english, shown);
      element.setAttribute(name, shown);
    }
  }
  for (const element of root.querySelectorAll("[data-i18n-html]")) {
    if (!element.dataset.i18nEnglish) element.dataset.i18nEnglish = element.innerHTML;
    element.innerHTML = language === "en" ? element.dataset.i18nEnglish : sq[element.dataset.i18nHtml] ?? element.dataset.i18nEnglish;
  }
}

function initialLanguage() {
  const fromAddress = new URL(location.href).searchParams.get("lang");
  if (supported.includes(fromAddress)) return fromAddress;
  try {
    const saved = localStorage.getItem("language");
    if (supported.includes(saved)) return saved;
  } catch {}
  return navigator.languages?.some(code => /^sq\b/i.test(code)) ? "sq" : "en";
}

let englishTitle, description, englishDescription;

export function setLanguage(next, { save = true } = {}) {
  if (!supported.includes(next)) return;
  language = next;
  if (englishTitle === undefined) {
    englishTitle = document.title;
    description = document.querySelector('meta[name="description"]');
    englishDescription = description?.content;
  }
  document.documentElement.lang = next;
  document.title = t(englishTitle);
  if (description) description.content = t(englishDescription);
  translateTree(document.body);
  document.querySelectorAll("[data-lang]").forEach(button => button.setAttribute("aria-pressed", String(button.dataset.lang === next)));
  if (save) {
    try { localStorage.setItem("language", next); } catch {}
    const address = new URL(location.href);
    if (next === "en") address.searchParams.delete("lang");
    else address.searchParams.set("lang", next);
    history.replaceState(history.state, "", address.href);
  }
  document.dispatchEvent(new CustomEvent("languagechange", { detail: next }));
}

export function startTranslation() {
  document.querySelectorAll("[data-lang]").forEach(button => button.addEventListener("click", () => setLanguage(button.dataset.lang)));
  const first = initialLanguage();
  if (first !== "en") setLanguage(first, { save: false });
  else document.querySelectorAll("[data-lang]").forEach(button => button.setAttribute("aria-pressed", String(button.dataset.lang === "en")));
}
